  let delta = vec2<f32>(receiverPixel - ownerPixel);
  let along = dot(delta, direction);
  let perpendicular = abs(delta.x * direction.y - delta.y * direction.x);
  return abs(along) <= radius + 1.0 && perpendicular <= 1.0;
